-- composition of rule kernels column_lifetime x grouping_sets (duckdb), template graft_union
WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT TRUE AS c0, BOOL_AND (FALSE) AS c1, [NULL]::text[] AS c2 FROM (SELECT * FROM rc UNION ALL SELECT * FROM rc WHERE (SELECT count(*) FROM (SELECT AGE ((MAX ('1999-12-31 23:59:59.999999+05:30'::timestamptz) OVER (PARTITION BY 16) - '-1 month'::interval), DATE_TRUNC ('year', (SELECT MIN ('1999-12-31 23:59:59.999999+05:30'::timestamptz) FROM t4 AS a1))) AS c0, 45 AS c1, 40 AS c2) AS kb) < 0) AS a1 GROUP BY ROLLUP (a1.c0) UNION (SELECT FALSE AS c0, TRUE AS c1, []::text[] AS c2 UNION SELECT TRUE AS c0, TRUE AS c1, []::text[] AS c2);
